window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-17291\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκαταφρόνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6052 na letra ε · nº geral 17291</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se pode facilmente desconsiderar; desprezível. 〈εὖ, καταφρονέω〉</p></section></article>\n<article id=\"entry-dgp-17292\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκαταφρονήτως</h1><div class=\"entry-meta\"><span>DGP · ordem 6053 na letra ε · nº geral 17292</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo desprezível.</p></section></article>\n<article id=\"entry-dgp-17293\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκατέργαστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6054 na letra ε · nº geral 17293</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de assimilar, de elaborar 2 fácil de cumprir, de executar 3 fácil de submeter ou de conquistar. 〈εὖ, κατεργάζομαι〉</p></section></article>\n<article id=\"entry-dgp-17294\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκατηγόρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6055 na letra ε · nº geral 17294</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de acusar, de criticar. 〈εὖ, κατηγορέω〉</p></section></article>\n<article id=\"entry-dgp-17295\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκέατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6056 na letra ε · nº geral 17295</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de fender, de rachar. 〈εὖ, κεάζω〉</p></section></article>\n<article id=\"entry-dgp-17296\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκέραστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6057 na letra ε · nº geral 17296</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem temperado (clima). 〈εὖ, κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-17297\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκερως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 6058 na letra ε · nº geral 17297</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de belos cornos. 〈εὖ, κέρας〉</p></section></article>\n<article id=\"entry-dgp-17298\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκηλήτειρα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 6059 na letra ε · nº geral 17298</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que acalma com carícias, gen. 〈εὖ, κηλέω〉</p></section></article>\n<article id=\"entry-dgp-17299\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6060 na letra ε · nº geral 17299</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem preocupações; calmo; tranqüilo: εὔκηλον βλέπειν eur. ter um olhar tranqüilo, εὔκηλον εὕδειν hom. dormir tranqüilamente 2 sem perturbação; impávido: εὔκηλοι πολέμιζον ὑπ᾽ αἰθέρι hom. combatiam impávidos sob o céu. 〈εὖ, κηλέω〉</p></section></article>\n<article id=\"entry-dgp-17300\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκίνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6061 na letra ε · nº geral 17300</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de mover, de mover-se; móvel; ágil 2 mutável 3 que se pode inclinar para algo, πρός e ac. 4 fácil de demover, de refutar. 〈εὖ, κινέω〉</p></section></article>\n<article id=\"entry-dgp-17301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλεής,</h1><div class=\"entry-meta\"><span>DGP · ordem 6062 na letra ε · nº geral 17301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋκλεής, ής, ές gen. εὐκλεέος-εὐκλεοῦς ilustre; glorioso. 〈εὖ, κλέος〉</p></section></article>\n<article id=\"entry-dgp-17302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6063 na letra ε · nº geral 17302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">glória; fama. 〈εὐκλεής〉</p></section></article>\n<article id=\"entry-dgp-17303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐκλείδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6064 na letra ε · nº geral 17303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Euclides, n. de homem. 〈εὐκλεής〉</p></section></article>\n<article id=\"entry-dgp-17304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλεΐη</h1><div class=\"entry-meta\"><span>DGP · ordem 6065 na letra ε · nº geral 17304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn., ἐϋκλεΐη ép. = εὔκλεια.</p></section></article>\n<article id=\"entry-dgp-17305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋκλειῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6066 na letra ε · nº geral 17305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ép. = εὐκλεῶς.</p></section></article>\n<article id=\"entry-dgp-17306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλεῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6067 na letra ε · nº geral 17306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. gloriosamente.</p></section></article>\n<article id=\"entry-dgp-17307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλήϊς,</h1><div class=\"entry-meta\"><span>DGP · ordem 6068 na letra ε · nº geral 17307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋκλήϊς, ϊδος (fem.) que fecha bem. 〈εὖ, κλείω1〉</p></section></article>\n<article id=\"entry-dgp-17308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκληρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6069 na letra ε · nº geral 17308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bom quinhão; boa sorte. 〈εὖ, κλῆρος〉</p></section></article>\n<article id=\"entry-dgp-17309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋκνήμις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 6070 na letra ε · nº geral 17309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de belas grevas; de belas cnêmides. 〈εὖ, κνημίς〉</p></section></article>\n<article id=\"entry-dgp-17310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκοίλιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6071 na letra ε · nº geral 17310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que alivia ou que solta o intestino. 〈εὖ, κοιλία〉</p></section></article>\n<article id=\"entry-dgp-17311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκοινόμητις</h1><div class=\"entry-meta\"><span>DGP · ordem 6072 na letra ε · nº geral 17311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. (masc., fem.): que vela pelo bem comum: προμαθὶς εὐκοινόμητις ἀρχά ésql. poder previdente, atento ao bem comum. 〈εὖ, κοινός, μῆτις〉</p></section></article>\n<article id=\"entry-dgp-17312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκοινωνησία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6073 na letra ε · nº geral 17312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sociabilidade. 〈εὐκοινώνητος〉</p></section></article>\n<article id=\"entry-dgp-17313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκοινώνητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6074 na letra ε · nº geral 17313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de trato fácil; comunicativo 2 sociável; conciliador. 〈εὖ, κοινωνέω〉</p></section></article>\n<article id=\"entry-dgp-17314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκολία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6075 na letra ε · nº geral 17314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 humor complacente; boa índole 2 contentamento; satisfação 3 boa disposição; agilidade; flexibilidade (do corpo). 〈εὔκολος〉</p></section></article>\n<article id=\"entry-dgp-17315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6076 na letra ε · nº geral 17315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 complacente; de bom humor; fácil de satisfazer, dat. ou πρός e ac. 2 afável; benevolente com alguém 3 que se deixa levar facilmente a; inclinado a, dat. ou πρός ac. 4 ágil; flexível.</p></section></article>\n<article id=\"entry-dgp-17316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκόλως</h1><div class=\"entry-meta\"><span>DGP · ordem 6077 na letra ε · nº geral 17316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com bom humor; amavelmente 2 com agilidade; com flexibilidade.</p></section></article>\n<article id=\"entry-dgp-17317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκομιδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6078 na letra ε · nº geral 17317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem cuidado. 〈εὖ, κομιδή〉</p></section></article>\n<article id=\"entry-dgp-17318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6079 na letra ε · nº geral 17318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de belo velo; de bela cabeleira. 〈εὖ, κόμη〉</p></section></article>\n<article id=\"entry-dgp-17319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκοπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6080 na letra ε · nº geral 17319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de trabalhar; fácil. 〈εὖ, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-17320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκοσμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6081 na letra ε · nº geral 17320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">boa ordem; conduta regrada; decência. 〈εὔκοσμος〉</p></section></article>\n<article id=\"entry-dgp-17321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκοσμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6082 na letra ε · nº geral 17321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de boa ordem; bem ordenado 2 decoroso; decente ♦ τὸ εὔκοσμον 3 boa ordem 4 conduta regrada; decência. 〈εὖ, κόσμος〉</p></section></article>\n<article id=\"entry-dgp-17322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκόσμως</h1><div class=\"entry-meta\"><span>DGP · ordem 6083 na letra ε · nº geral 17322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em boa ordem 2 com ornamento.</p></section></article>\n<article id=\"entry-dgp-17323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκραιρος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6084 na letra ε · nº geral 17323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰκραιρος, ος, ον de belos cornos (boi). 〈εὖ, κραῖρα〉</p></section></article>\n<article id=\"entry-dgp-17324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκρατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6085 na letra ε · nº geral 17324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem misturado (bebida) 2 bem temperado (clima) 3 bem regrado; equilibrado; moderado 4 de humor constante; doce. 〈εὖ, κεράννυμι〉</p></section></article>\n<article id=\"entry-dgp-17325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκρινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6086 na letra ε · nº geral 17325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separar bem; escolher com cuidado 2 pôr em ordem. 〈εὖ, κρίνω〉</p></section></article>\n<article id=\"entry-dgp-17326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκρινής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6087 na letra ε · nº geral 17326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 separado; destacado 2 bem distinto; claro 3 bem disposto; posto em ordem 4 sadio; são 5 que superou a crise; convalescente (corpo) 6 Medic. que indica superação da crise; favorável (sintoma) 7 Medic. que evolui com facilidade para a crise (doença). 〈εὖ, κρίνω〉</p></section></article>\n<article id=\"entry-dgp-17327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκρινῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6088 na letra ε · nº geral 17327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em boa ordem 2 distintamente; claramente.</p></section></article>\n<article id=\"entry-dgp-17328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκριτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6089 na letra ε · nº geral 17328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de distinguir; claro; evidente. 〈εὖ, κρίνω〉</p></section></article>\n<article id=\"entry-dgp-17329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκρότητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6090 na letra ε · nº geral 17329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem batido sobre a bigorna; bem forjado. 〈εὖ, κροτέω〉</p></section></article>\n<article id=\"entry-dgp-17330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκταῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6091 na letra ε · nº geral 17330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 consagrado ou prometido por voto; votivo 2 desejado 3 invocado com preces: εὐκταία φάτις ésql. palavra de imprecação ♦ τὰ εὐκταῖα 4 preces ou oferendas votivas. 〈εὐκτός〉</p></section></article>\n<article id=\"entry-dgp-17331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκτέανος1, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6092 na letra ε · nº geral 17331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rico. 〈εὖ, κτέανον〉</p></section></article>\n<article id=\"entry-dgp-17332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκτέανος2, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6093 na letra ε · nº geral 17332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de fibras tenras; fácil de partir, de cortar. 〈εὖ, κτείς〉</p></section></article>\n<article id=\"entry-dgp-17333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 6094 na letra ε · nº geral 17333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὔχομαι.</p></section></article>\n<article id=\"entry-dgp-17334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκτίμενος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6095 na letra ε · nº geral 17334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐϋκτίμενος, η, ον 1 bem construído 2 bem trabalhado; bem ordenado.</p></section></article>\n<article id=\"entry-dgp-17335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκτιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6096 na letra ε · nº geral 17335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem construído. 〈εὖ, κτίζω〉</p></section></article>\n<article id=\"entry-dgp-17336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6097 na letra ε · nº geral 17336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 desejado 2 desejável. 〈εὔχομαι〉</p></section></article>\n<article id=\"entry-dgp-17337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκυκλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6098 na letra ε · nº geral 17337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem redondo 2 circular (dança) 3 de belas rodas (carro). 〈εὖ, κύκλος〉</p></section></article>\n<article id=\"entry-dgp-17338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλάβεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6099 na letra ε · nº geral 17338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 precaução; cautela; circunspecção com ou contra algo, gen., para que não, μή e inf. 2 escrúpulo; temor 3 temor dos deuses 4 piedade 5 medo. 〈εὐλαβής〉</p></section></article>\n<article id=\"entry-dgp-17339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 6100 na letra ε · nº geral 17339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. εὐλαβούμην e ηὐλαβούμην, fut. εὐλαβήσομαι e εὐλαβηθήσομαι, aor. εὐλαβήθην, perf. desus.) 1 tomar cuidado com; precaver-se contra, ac. ou περί e ac., ἀμφί e dat. ou περί e gen., para que, ὅπως e fut. ind., ou com inf., para que não, μή e inf., μή ou ὅπως μή e subj. ou μή e fut. ind. 2 estar atento 3 cuidar de; honrar; ter em consideração; respeitar 4 bíbl. ser temente a Deus. 〈εὐλαβής〉</p></section></article>\n<article id=\"entry-dgp-17340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6101 na letra ε · nº geral 17340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que toma precauções; que se mantém em guarda; circunspecto 2 tímido; receoso; timorato 3 empreendido com cautela; feito com prudência 4 de que é fácil se precaver 5 bíbl. temente a Deus; devoto. 〈εὖ, λαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-17341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 6102 na letra ε · nº geral 17341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de εὐλαβέομαι.</p></section></article>\n<article id=\"entry-dgp-17342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβουμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 6103 na letra ε · nº geral 17342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com prudência; prudentemente. 〈εὐλαβέομαι〉</p></section></article>\n<article id=\"entry-dgp-17343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6104 na letra ε · nº geral 17343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com precaução; com circunspecção; com cautela 2 segurando com força.</p></section></article>\n<article id=\"entry-dgp-17344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6105 na letra ε · nº geral 17344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. fut. dór. εὐλαξεῖν) lavrar ou cavar a terra. 〈εὐλάκα〉</p></section></article>\n<article id=\"entry-dgp-17345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλάκα</h1><div class=\"entry-meta\"><span>DGP · ordem 6106 na letra ε · nº geral 17345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só dat. εὐλάκᾳ (ἡ) lac. = αὖλαξ.</p></section></article>\n<article id=\"entry-dgp-17346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλείμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6107 na letra ε · nº geral 17346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος de belos prados. 〈εὖ, λειμών〉</p></section></article>\n<article id=\"entry-dgp-17347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλεκτρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6108 na letra ε · nº geral 17347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cujo leito é desejável 2 propício aos enlaces; que proporciona alegria de amor. 〈εὖ, λέκτρον〉</p></section></article>\n<article id=\"entry-dgp-17348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλεξις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 6109 na letra ε · nº geral 17348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de bela linguagem; de belas palavras. 〈εὖ, λέξις〉</p></section></article>\n<article id=\"entry-dgp-17349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6110 na letra ε · nº geral 17349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 verme; larva 2 minhoca.</p></section></article>\n<article id=\"entry-dgp-17350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔληκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6111 na letra ε · nº geral 17350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cessa com facilidade. 〈εὖ, λήγω〉</p></section></article>\n<article id=\"entry-dgp-17351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔληπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6112 na letra ε · nº geral 17351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de apanhar, de apreender 2 fácil de conquistar, de pilhar 3 fácil de obter. 〈εὖ, λα­μ­βάνω〉</p></section></article>\n<article id=\"entry-dgp-17352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλήπτως</h1><div class=\"entry-meta\"><span>DGP · ordem 6113 na letra ε · nº geral 17352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo fácil de apanhar, de apreender.</p></section></article>\n<article id=\"entry-dgp-17353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔληρα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 6114 na letra ε · nº geral 17353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rédeas; freios.</p></section></article>\n<article id=\"entry-dgp-17354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6115 na letra ε · nº geral 17354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falar bem de alguém, ac.; louvar; elogiar 2 demonstrar consideração por alguém, ac.; honrar 3 bíbl. abençoar alguém, ac. ou dat. 4 bíbl. pronunciar uma imprecação. 〈εὔλογος〉</p></section></article>\n<article id=\"entry-dgp-17355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6116 na letra ε · nº geral 17355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. bendito; abençoado. 〈εὐλογέω〉</p></section></article>\n<article id=\"entry-dgp-17356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6117 na letra ε · nº geral 17356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 belas palavras 2 louvor; elogio 3 bíbl. ação de abençoar; bendição 4 bíbl. benefício; benfeitoria 5 bíbl. esmola. 〈εὔλογος〉</p></section></article>\n<article id=\"entry-dgp-17357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογιστέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6118 na letra ε · nº geral 17357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">agir com prudência. 〈εὐλόγιστος〉</p></section></article>\n<article id=\"entry-dgp-17358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογιστία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6119 na letra ε · nº geral 17358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prudência; cautela. 〈εὐλόγιστος〉</p></section></article>\n<article id=\"entry-dgp-17359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλόγιστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6120 na letra ε · nº geral 17359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que raciocina bem; sensato; prudente 2 bem avaliado; bem calculado ♦ τὸ εὐλόγιστον 3 bom senso; prudência. 〈εὖ, λογίζομαι〉</p></section></article>\n<article id=\"entry-dgp-17360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλογος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6121 na letra ε · nº geral 17360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fundado na razão; sensato 2 plausível; verossímil ♦ τὸ εὔλογον 3 razão plausível; verossimilhança. 〈εὖ, λέγω3〉</p></section></article>\n<article id=\"entry-dgp-17361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλογχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6122 na letra ε · nº geral 17361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem favorecido pela sorte; felizardo; afortunado. 〈εὖ, λάγχάνω〉</p></section></article>\n<article id=\"entry-dgp-17362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλόγως</h1><div class=\"entry-meta\"><span>DGP · ordem 6123 na letra ε · nº geral 17362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo verossímil; razoalvelmente.</p></section></article>\n<article id=\"entry-dgp-17363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλοιδόρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6124 na letra ε · nº geral 17363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de criticar; exposto aos insultos, às injúrias. 〈εὖ, λοιδορέω〉</p></section></article>\n<article id=\"entry-dgp-17364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6125 na letra ε · nº geral 17364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de belo penacho (capacete). 〈εὖ, λόφος〉</p></section></article>\n<article id=\"entry-dgp-17365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλοχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6126 na letra ε · nº geral 17365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">propício aos partos. 〈εὖ, λέχος〉</p></section></article>\n<article id=\"entry-dgp-17366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλύρας, α</h1><div class=\"entry-meta\"><span>DGP · ordem 6127 na letra ε · nº geral 17366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. = εὔλυρος.</p></section></article>\n<article id=\"entry-dgp-17367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6128 na letra ε · nº geral 17367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de lira melodiosa. 〈εὖ, λύρα〉</p></section></article>\n<article id=\"entry-dgp-17368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6129 na letra ε · nº geral 17368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de desatar 2 fácil de romper 3 frágil; débil 4 fácil de relaxar, de soltar. 〈εὖ, λύω〉</p></section></article>\n<article id=\"entry-dgp-17369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμάθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6130 na letra ε · nº geral 17369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">facilidade de aprender. 〈εὐμαθής〉</p></section></article>\n<article id=\"entry-dgp-17370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6131 na letra ε · nº geral 17370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de aprender, de compreender, de reconhecer 2 que se aprende com facilidade 3 bem conhecido. 〈εὖ, μανθάνω〉</p></section></article>\n<article id=\"entry-dgp-17371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαθία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6132 na letra ε · nº geral 17371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐμάθεια.</p></section></article>\n<article id=\"entry-dgp-17372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαθῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6133 na letra ε · nº geral 17372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. aprendendo ou compreendendo com facilidade.</p></section></article>\n<article id=\"entry-dgp-17373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμάκης</h1><div class=\"entry-meta\"><span>DGP · ordem 6134 na letra ε · nº geral 17373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = εὐμήκης.</p></section></article>\n<article id=\"entry-dgp-17374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμαλος</h1><div class=\"entry-meta\"><span>DGP · ordem 6135 na letra ε · nº geral 17374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = εὔμηλος.</p></section></article>\n<article id=\"entry-dgp-17375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμάρεια, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 6136 na letra ε · nº geral 17375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. εὐμαρίη, ης (ἡ) 1 facilidade; comodidade: οὐκ εὐμαρείᾳ χρώμενος πολλῇ sóf. não tendo grande facilidade, εὐμάρειά ἐστι, inf. é cômodo, é facil 2 destreza; habilidade 3 meio fácil; expediente 4 bom funcionamento dos intestinos; facilidade na evacuação: εὐμαρίῃ χρῆσθαι her. fazer as necessidades. 〈εὐμαρής〉</p></section></article>\n<article id=\"entry-dgp-17376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6137 na letra ε · nº geral 17376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil; cômodo: εὐμαρές ἐστι, inf. é fácil, ἐν εὐμαρεῖ facilmente 2 que facilita; complacente 3 cortês; gentil. 〈εὖ, μάρη〉</p></section></article>\n<article id=\"entry-dgp-17377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαρίη</h1><div class=\"entry-meta\"><span>DGP · ordem 6138 na letra ε · nº geral 17377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = εὐμάρεια.</p></section></article>\n<article id=\"entry-dgp-17378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμαρις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6139 na letra ε · nº geral 17378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">calçado asiático feito de pele.</p></section></article>\n<article id=\"entry-dgp-17379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμαρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6140 na letra ε · nº geral 17379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 comodamente 2 facilmente.</p></section></article>\n<article id=\"entry-dgp-17380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμεγέθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 6141 na letra ε · nº geral 17380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de bom tamanho; grande; amplo. 〈εὖ, μέγεθος〉</p></section></article>\n<article id=\"entry-dgp-17381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμέλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6142 na letra ε · nº geral 17381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">harmonia; bela melodia. 〈εὖ, μέλος〉</p></section></article>\n<article id=\"entry-dgp-17382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμένεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6143 na letra ε · nº geral 17382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 benevolência; bondade: ἡ πρὸς τὸ θεῖον εὐμένεια tuc. o favor dos deuses 2 suavidade (do odor). 〈εὐμενής〉</p></section></article>\n<article id=\"entry-dgp-17383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 6144 na letra ε · nº geral 17383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) benévolo; amigo. 〈εὐμενής〉</p></section></article>\n<article id=\"entry-dgp-17384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6145 na letra ε · nº geral 17384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) 1 ser benévolo, bom, gentil para com alguém, dat. 2 tratar com bondade, com gentileza, ac..</p></section></article>\n<article id=\"entry-dgp-17385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενέως</h1><div class=\"entry-meta\"><span>DGP · ordem 6146 na letra ε · nº geral 17385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = εὐμενῶς.</p></section></article>\n<article id=\"entry-dgp-17386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6147 na letra ε · nº geral 17386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 benévolo; bom; gentil (pessoa) 2 bem disposto para algo com πρός e ac.; com alguém dat. 3 fácil; favorável; suave (coisa): ἐπ᾽ εὐμενεῖ τύχᾳ pínd. com sorte benigna, γῆ εὐμενὴς ἐναγωνίσασθαι tuc. terra favorável para um combate ♦ τὸ εὐμενές 4 benevolência. 〈εὖ, μένος〉</p></section></article>\n<article id=\"entry-dgp-17387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐμενίδες, ων (αἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6148 na letra ε · nº geral 17387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">as Eumênidas, lit. as Benevolentes, nome dado por eufem. às Erínias. 〈εὐμενής〉</p></section></article>\n<article id=\"entry-dgp-17388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 6149 na letra ε · nº geral 17388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. εὐμενιζόμην) tornar-se favorável; conciliar-se. 〈εὐμενής〉</p></section></article>\n<article id=\"entry-dgp-17389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμενῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6150 na letra ε · nº geral 17389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com benevolência.</p></section></article>\n<article id=\"entry-dgp-17390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμετάβλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6151 na letra ε · nº geral 17390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que muda com facilidade. 〈εὖ, μεταβάλλω〉</p></section></article>\n";
